import java.util.Scanner;

public class Words {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int size = sc.nextInt();
        String inputString = sc.next();
        char[] arrayChars = inputString.toCharArray();
        int[] segmentLengths = new int[size];
        int wordCount = 0;
        int segmentPointer = 0;
        for (int i = 0; i < size; i++) {
            segmentLengths[i] = 0;
        }
        int modeIndicator = 0;
        if (arrayChars[0] == '_') {
            modeIndicator = 0;
        } else if (arrayChars[0] == '(') {
            modeIndicator = 1;
        }
        for (int i = 0; i < size; i++) {
            if (modeIndicator == 0) {
                if (arrayChars[i] == '_') {
                    segmentPointer++;
                } else {
                    if (arrayChars[i] != '(') {
                        segmentLengths[segmentPointer]++;
                    } else if (arrayChars[i] == '(') {
                        modeIndicator = 1;
                    } else if (arrayChars[i] == ')') {
                        modeIndicator = 0;
                    }
                }
            } else {
                if (arrayChars[i] == ')') {
                    modeIndicator = 0;
                    segmentPointer++;
                } else if (i > 0) {
                    if (arrayChars[i - 1] == '(' || arrayChars[i - 1] == '_') {
                        if (arrayChars[i] != '_' && arrayChars[i] != '(') {
                            wordCount++;
                        }
                    }
                }
            }
        }
        // Sorting in descending order
        for (int i = 0; i < size; i++) {
            for (int j = i; j > 0; j--) {
                if (segmentLengths[j] > segmentLengths[j - 1]) {
                    int tempVal = segmentLengths[j];
                    segmentLengths[j] = segmentLengths[j - 1];
                    segmentLengths[j - 1] = tempVal;
                }
            }
        }
        System.out.println(segmentLengths[0]);
        System.out.println(wordCount);
    }
}
